using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Linq;using System.Windows.Forms;
namespace IslandIntegrated {
 public sealed class GridDisplacement {
  sealed class Node {public RectangleF Current,Target;public float X,Y,W,H;}
  readonly Dictionary<string,Node> nodes=new Dictionary<string,Node>();long last,retarget;bool initialized;public bool Moving{get;private set;}
  public Dictionary<string,RectangleF> Current {get{return nodes.ToDictionary(p=>p.Key,p=>p.Value.Current);}}
  public IEnumerable<KeyValuePair<string,RectangleF>> Entries {get{foreach(var p in nodes)yield return new KeyValuePair<string,RectangleF>(p.Key,p.Value.Current);}}
  public RectangleF Get(string key){return nodes[key].Current;}
  static float Step(float value,float target,ref float velocity,double dt){const double omega=26,zeta=.68;double rate=zeta*omega,wd=omega*Math.Sqrt(1-zeta*zeta),decay=Math.Exp(-rate*dt),cos=Math.Cos(wd*dt),sin=Math.Sin(wd*dt),d=value-target,v=velocity;double result=target+decay*(d*cos+(v+rate*d)/wd*sin);velocity=(float)(decay*(v*cos-(rate*v+omega*omega*d)/wd*sin));return (float)result;}
  public void Advance(long now){if(!Moving)return;double dt=Math.Max(0,Math.Min(.1,(now-last)/1000d));last=now;bool moving=false;foreach(var pair in nodes){var n=pair.Value;var r=n.Current;var t=n.Target;r.X=Step(r.X,t.X,ref n.X,dt);r.Y=Step(r.Y,t.Y,ref n.Y,dt);r.Width=Math.Max(1,Step(r.Width,t.Width,ref n.W,dt));r.Height=Math.Max(1,Step(r.Height,t.Height,ref n.H,dt));bool close=Math.Abs(r.X-t.X)<.12&&Math.Abs(r.Y-t.Y)<.12&&Math.Abs(r.Width-t.Width)<.12&&Math.Abs(r.Height-t.Height)<.12&&Math.Abs(n.X)<2&&Math.Abs(n.Y)<2&&Math.Abs(n.W)<2&&Math.Abs(n.H)<2;if(close||now-retarget>=700){n.Current=t;n.X=n.Y=n.W=n.H=0;}else{n.Current=r;moving=true;}}Moving=moving;}
  public bool Set(Dictionary<string,Rectangle> plan,long now,bool reduced){if(initialized)Advance(now);else{initialized=true;last=now;}bool changed=nodes.Count!=plan.Count||plan.Any(p=>!nodes.ContainsKey(p.Key)||nodes[p.Key].Target!=(RectangleF)p.Value);if(!changed){if(reduced&&Moving){foreach(var n in nodes.Values){n.Current=n.Target;n.X=n.Y=n.W=n.H=0;}Moving=false;}return false;}foreach(string key in nodes.Keys.Except(plan.Keys).ToArray())nodes.Remove(key);foreach(var p in plan){Node n;if(!nodes.TryGetValue(p.Key,out n)){n=new Node{Current=p.Value};nodes[p.Key]=n;}n.Target=p.Value;if(reduced){n.Current=n.Target;n.X=n.Y=n.W=n.H=0;}}last=retarget=now;Moving=!reduced&&nodes.Values.Any(n=>n.Current!=n.Target);return true;}
 }

 public static class DragTarget {
  public static string Find(Dictionary<string,Rectangle> plan,Point logical,int width){if(logical.X<0||logical.X>=width||logical.Y<0)return null;foreach(var p in plan)if(p.Value.Contains(logical))return p.Key;if(plan.Count==0)return null;var nearest=plan.OrderBy(p=>Math.Abs(p.Value.Top+p.Value.Height/2-logical.Y)+Math.Abs(p.Value.Left+p.Value.Width/2-logical.X)).First();return nearest.Key;}
 }
 public static class DragSnapshot {
  public static void ClearConnectedKey(Bitmap image,Color key){var rect=new Rectangle(0,0,image.Width,image.Height);var bits=image.LockBits(rect,ImageLockMode.ReadWrite,PixelFormat.Format32bppArgb);try{int stride=Math.Abs(bits.Stride);if(bits.Stride<0)throw new InvalidOperationException("Unsupported snapshot row order");var bytes=new byte[stride*image.Height];System.Runtime.InteropServices.Marshal.Copy(bits.Scan0,bytes,0,bytes.Length);var queue=new int[image.Width*image.Height];int head=0,tail=0;Action<int,int> add=(x,y)=>{int p=y*stride+x*4;if(bytes[p+3]!=0&&bytes[p]==key.B&&bytes[p+1]==key.G&&bytes[p+2]==key.R){bytes[p+3]=0;queue[tail++]=y*image.Width+x;}};for(int x=0;x<image.Width;x++){add(x,0);add(x,image.Height-1);}for(int y=1;y<image.Height-1;y++){add(0,y);add(image.Width-1,y);}while(head<tail){int p=queue[head++],x=p%image.Width,y=p/image.Width;if(x>0)add(x-1,y);if(x+1<image.Width)add(x+1,y);if(y>0)add(x,y-1);if(y+1<image.Height)add(x,y+1);}int radius=Math.Min(24,Math.Min(image.Width,image.Height)/2);for(int y=0;y<radius;y++)for(int x=0;x<radius;x++){double dx=radius-x-.5,dy=radius-y-.5;if(dx*dx+dy*dy<=radius*radius)continue;bytes[y*stride+x*4+3]=0;bytes[y*stride+(image.Width-1-x)*4+3]=0;bytes[(image.Height-1-y)*stride+x*4+3]=0;bytes[(image.Height-1-y)*stride+(image.Width-1-x)*4+3]=0;}System.Runtime.InteropServices.Marshal.Copy(bytes,0,bits.Scan0,bytes.Length);}finally{image.UnlockBits(bits);}}
 }

 public sealed class DragInsertionPlan {
  readonly List<Card> original,others;readonly Card dragged;readonly Rectangle[] slots;readonly Point grab;readonly int width;public int Index{get;private set;}
  public DragInsertionPlan(IList<Card> cards,string id,int columnWidth,Point grabOffset){original=new List<Card>(cards);dragged=original.Single(c=>c.Id==id);Index=original.IndexOf(dragged);others=original.Where(c=>c!=dragged).ToList();width=columnWidth;grab=grabOffset;slots=new Rectangle[cards.Count];for(int i=0;i<slots.Length;i++){var order=new List<Card>(others);order.Insert(i,dragged);slots[i]=WidgetGrid.Arrange(order,width)[id];}}
  double Distance(int index,Point point){var r=slots[index];double x=point.X-grab.X+r.Width/2d-(r.Left+r.Width/2d),y=point.Y-grab.Y+r.Height/2d-(r.Top+r.Height/2d);return Math.Sqrt(x*x+y*y);}
  public bool Update(Point logical){if(logical.X<0||logical.X>=width||logical.Y<0)return false;int best=Index;double current=Distance(Index,logical),distance=current;for(int i=0;i<slots.Length;i++){double next=Distance(i,logical);if(next<distance-.01){best=i;distance=next;}}if(best==Index||distance+16>=current)return false;Index=best;return true;}
  public void Apply(Layout layout){var order=new List<Card>(others);order.Insert(Index,dragged);layout.Cards=order;}
 }

 public sealed class DragPreview:Control {
  readonly Dictionary<string,Bitmap> images=new Dictionary<string,Bitmap>();readonly GridDisplacement motion=new GridDisplacement(),release=new GridDisplacement();readonly Timer timer=new Timer{Interval=16};readonly string dragged;Point pointer,grab=new Point(60,18);bool releasing,completed;
  public Dictionary<string,Rectangle> Plan=new Dictionary<string,Rectangle>();public bool ReducedMotion;public event EventHandler Settled;public bool IsSettling{get{return releasing&&!completed;}}
  public DragPreview(IEnumerable<Control> controls,string id){dragged=id;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.Opaque,true);BackColor=Palette.Base;foreach(var control in controls){if(!(control.Tag is string))continue;var image=GlassComposition.CaptureControl(control);images[(string)control.Tag]=image;}timer.Tick+=(s,e)=>Frame();}
  public void SetGrab(Point offset){grab=offset;}
  void Frame(){if(IsDisposed)return;long now=PreviewClock.NowMs;motion.Advance(now);release.Advance(now);Invalidate();if(!motion.Moving&&!release.Moving){timer.Stop();if(releasing&&!completed){completed=true;var h=Settled;if(h!=null)h(this,EventArgs.Empty);}}}
  public void Present(Dictionary<string,Rectangle> plan,Point cursor){if(IsDisposed||completed)return;long now=PreviewClock.NowMs;bool moved=pointer!=cursor,changed=motion.Set(plan,now,ReducedMotion);if(changed||Plan.Count==0)Plan=new Dictionary<string,Rectangle>(plan);if(!releasing)pointer=cursor;if(releasing){Rectangle destination;if(plan.TryGetValue(dragged,out destination))release.Set(new Dictionary<string,Rectangle>{{dragged,destination}},now,ReducedMotion);}if(!changed&&!moved)return;if(motion.Moving||release.Moving)timer.Start();Invalidate();}
  public void Release(Dictionary<string,Rectangle> plan){if(releasing||IsDisposed)return;Bitmap image;Rectangle slot;if(!images.TryGetValue(dragged,out image)||!plan.TryGetValue(dragged,out slot)){completed=true;var h=Settled;if(h!=null)h(this,EventArgs.Empty);return;}long now=PreviewClock.NowMs;motion.Set(plan,now,ReducedMotion);Plan=new Dictionary<string,Rectangle>(plan);release.Set(new Dictionary<string,Rectangle>{{dragged,new Rectangle(pointer.X-grab.X,pointer.Y-grab.Y,image.Width,image.Height)}},now,true);release.Set(new Dictionary<string,Rectangle>{{dragged,slot}},now,ReducedMotion);releasing=true;timer.Start();Frame();}
  void PaintLanding(Graphics g,Rectangle slot){var r=Rectangle.Inflate(slot,-4,-4);using(var path=GlassSurface.Path(r,20))using(var pen=new Pen(Color.FromArgb(255,Palette.Text.R,Palette.Text.G,Palette.Text.B),Math.Max(1,DeviceDpi/96f)))g.DrawPath(pen,path);}
  protected override void OnPaint(PaintEventArgs e){var watch=System.Diagnostics.Stopwatch.StartNew();if(GlassComposition.Active){var mode=e.Graphics.CompositingMode;e.Graphics.CompositingMode=CompositingMode.SourceCopy;using(var clear=new SolidBrush(Color.Transparent))e.Graphics.FillRectangle(clear,ClientRectangle);e.Graphics.CompositingMode=mode;}else e.Graphics.Clear(BackColor);foreach(var p in motion.Entries){Bitmap image;if(p.Key!=dragged&&images.TryGetValue(p.Key,out image))e.Graphics.DrawImage(image,p.Value);}Bitmap floating;Rectangle slot;if(images.TryGetValue(dragged,out floating)&&Plan.TryGetValue(dragged,out slot)){if(!releasing)PaintLanding(e.Graphics,Rectangle.Round(motion.Get(dragged)));Point location=releasing?Point.Round(release.Get(dragged).Location):new Point(pointer.X-grab.X,pointer.Y-grab.Y);e.Graphics.DrawImageUnscaled(floating,location);}TransitionMetrics.Record("drag-preview-paint",watch.Elapsed.TotalMilliseconds);}
  protected override void Dispose(bool disposing){if(disposing){completed=true;Settled=null;timer.Stop();timer.Dispose();foreach(var image in images.Values)image.Dispose();images.Clear();}base.Dispose(disposing);}
 }

}
